import{_ as e,o as l,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"10 years of Ceph at Walmart","description":"","frontmatter":{"title":"10 years of Ceph at Walmart","date":"2026-04-20T00:00:00.000Z","updated":"2026-04-21T00:00:00.000Z","tags":["Ceph","distributed storage","production operations","performance tuning","bluestore"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/10_years_of_Ceph_at_Walmart.md","filePath":"posts/2026/10_years_of_Ceph_at_Walmart.md","lastUpdated":1780459816000}'),o={name:"posts/2026/10_years_of_Ceph_at_Walmart.md"};function t(h,a,n,s,u,c){return l(),i("div",null,[...a[0]||(a[0]=[r('<h2 id="演讲者介绍" tabindex="-1">演讲者介绍 <a class="header-anchor" href="#演讲者介绍" aria-label="Permalink to &quot;演讲者介绍&quot;">​</a></h2><p>本次演讲由沃尔玛三位资深工程师联合呈现：</p><ul><li><strong>Anupam Thacker</strong>：沃尔玛首席软件工程师，在沃尔玛工作整 10 年，此前也曾在另一家大型公司成功运营 Ceph 生产环境。</li><li><strong>Bharat</strong>：同样在沃尔玛工作超过 10 年，主要负责运维工作，确保集群稳定运行。</li><li><strong>Prajwal</strong>：在沃尔玛工作超过 4 年，此前在电信公司有丰富的 Ceph 使用经验，涵盖 OpenStack 和 Kubernetes 工作负载。</li></ul><h2 id="硬件演进历程-2015–2025" tabindex="-1">硬件演进历程（2015–2025） <a class="header-anchor" href="#硬件演进历程-2015–2025" aria-label="Permalink to &quot;硬件演进历程（2015–2025）&quot;">​</a></h2><h3 id="_2015-年-借用硬件起步" tabindex="-1">2015 年：借用硬件起步 <a class="header-anchor" href="#_2015-年-借用硬件起步" aria-label="Permalink to &quot;2015 年：借用硬件起步&quot;">​</a></h3><ul><li>使用借来的节点，从 block storage 全SSD 方案起步，明确不使用机械硬盘</li><li>单 10GbE 网络连接</li><li>老旧 Intel 双路 CPU硬件（1U/2U 混合）</li><li>运行 Ceph Hammer，使用 FileStore + XFS + LevelDB</li></ul><h3 id="_2015-年底-首批生产硬件" tabindex="-1">2015 年底：首批生产硬件 <a class="header-anchor" href="#_2015-年底-首批生产硬件" aria-label="Permalink to &quot;2015 年底：首批生产硬件&quot;">​</a></h3><ul><li>升级至双 10GbE 以太网</li><li>驱动器密度翻倍，使用 1.92TB SATA 盘</li><li>引入 Intel P3700 NVMe 驱动器（2014 年发布）</li></ul><h3 id="_2016-年-升级至-ceph-jewel" tabindex="-1">2016 年：升级至 Ceph Jewel <a class="header-anchor" href="#_2016-年-升级至-ceph-jewel" aria-label="Permalink to &quot;2016 年：升级至 Ceph Jewel&quot;">​</a></h3><ul><li>仍使用 FileStore + LevelDB</li></ul><h3 id="_2018-年-升级至-ceph-luminous" tabindex="-1">2018 年：升级至 Ceph Luminous <a class="header-anchor" href="#_2018-年-升级至-ceph-luminous" aria-label="Permalink to &quot;2018 年：升级至 Ceph Luminous&quot;">​</a></h3><ul><li>完成 LevelDB 到 RocksDB 的原地转换（逐个 OSD 停机、flush journal、执行 map 转换、重启）</li><li>整体过程较为顺利</li></ul><h3 id="_2018–2019-年-迁移至-ceph-mimic-bluestore" tabindex="-1">2018–2019 年：迁移至 Ceph Mimic + BlueStore <a class="header-anchor" href="#_2018–2019-年-迁移至-ceph-mimic-bluestore" aria-label="Permalink to &quot;2018–2019 年：迁移至 Ceph Mimic + BlueStore&quot;">​</a></h3><ul><li>对 BlueStore 保持谨慎态度，认为自研文件系统风险较高</li><li>长期停留在 Luminous/Mimic 版本</li></ul><h3 id="_2021-年-升级至-ceph-nautilus" tabindex="-1">2021 年：升级至 Ceph Nautilus <a class="header-anchor" href="#_2021-年-升级至-ceph-nautilus" aria-label="Permalink to &quot;2021 年：升级至 Ceph Nautilus&quot;">​</a></h3><ul><li>首次在容器中运行 Ceph</li><li>首次正式使用 BlueStore</li><li>从 2x replication 升级至 3x replication（此前长期使用 2x，虽有争议但运行成功）</li><li>驱动器密度持续翻倍：1.92TB → 3.84TB → 7.68TB</li><li>从 SATA 切换至 SAS（解决长时间 backfilling 时SATA 盘垃圾回收导致的性能下降问题）</li><li>从 Intel P3700 切换至更快的 Optane 驱动器</li></ul><h3 id="_2022-年-全面转向-nvme" tabindex="-1">2022 年：全面转向 NVMe <a class="header-anchor" href="#_2022-年-全面转向-nvme" aria-label="Permalink to &quot;2022 年：全面转向 NVMe&quot;">​</a></h3><ul><li>从 SAS/SATA 全面切换至 NVMe</li><li>为控制成本，采用 16 核 AMD EPYC 处理器（后来证明算力不足）</li><li>取消独立启动盘，用 NVMe 分区启动（后来证明是错误决策，已改回独立启动盘）</li><li>快速升级至 32 核，随后升级至 48 核 CPU</li></ul><h3 id="_2023-年-升级至-ceph-quincy" tabindex="-1">2023 年：升级至 Ceph Quincy <a class="header-anchor" href="#_2023-年-升级至-ceph-quincy" aria-label="Permalink to &quot;2023 年：升级至 Ceph Quincy&quot;">​</a></h3><ul><li>跳过 Pacific 版本，主要原因是担心 cephadm orchestrator 在大规模集群上的扩展性问题</li><li>实际操作：先升级至 Pacific，24 小时内再升级至 Quincy</li><li>全面采用 cephadm orchestrator</li><li>网络升级至单路 100GbE，正在推进双路 100GbE</li><li>探索 Layer 3 高可用方案（不使用 LACP 等 Layer 2 方案）</li></ul><h3 id="_2024–2025-年-升级至-ceph-reef-进行中" tabindex="-1">2024–2025 年：升级至 Ceph Reef（进行中） <a class="header-anchor" href="#_2024–2025-年-升级至-ceph-reef-进行中" aria-label="Permalink to &quot;2024–2025 年：升级至 Ceph Reef（进行中）&quot;">​</a></h3><ul><li>目前约完成一半，Reef 已接近 EOL 但沃尔玛才刚开始使用</li><li>受零售业务特性影响，每年有较长的变更冻结期（节假日旺季），导致版本升级节奏保守，通常滞后约半年</li></ul><h2 id="监控与可观测性" tabindex="-1">监控与可观测性 <a class="header-anchor" href="#监控与可观测性" aria-label="Permalink to &quot;监控与可观测性&quot;">​</a></h2><h3 id="核心理念" tabindex="-1">核心理念 <a class="header-anchor" href="#核心理念" aria-label="Permalink to &quot;核心理念&quot;">​</a></h3><p>大规模运营成功的关键之一是完善的监控体系。沃尔玛从单个集群到数十个集群，均需要全面的可观测性。</p><h3 id="监控架构" tabindex="-1">监控架构 <a class="header-anchor" href="#监控架构" aria-label="Permalink to &quot;监控架构&quot;">​</a></h3><ul><li>从各子集群采集全量指标</li><li>通过 node exporter 采集各节点数据</li><li>汇总至统一的上层 dashboard</li></ul><h3 id="端到端延迟监控-重点" tabindex="-1">端到端延迟监控（重点） <a class="header-anchor" href="#端到端延迟监控-重点" aria-label="Permalink to &quot;端到端延迟监控（重点）&quot;">​</a></h3><p>Ceph 原生的延迟监控存在明显不足，沃尔玛采用外部测量方案：</p><ul><li>为每个集群部署若干 OpenStack VM</li><li>持续发送单队列深度、单 IO、4K 写请求</li><li>每 5 分钟采集一次数据并绘图</li></ul><p><strong>实际案例对比</strong>：在一次 Quincy → Reef 的大版本升级过程中（集群规模约 100–200 节点）：</p><ul><li>外部监控显示：升级期间（约 6–7 小时）最大延迟在 1–5 秒之间，PG pering 过程是尾延迟的主要来源</li><li>Ceph dashboard 显示：同一时间段最大延迟仅 30 微秒——<strong>完全失真，毫无参考价值</strong></li></ul><p>这一对比清晰说明了外部端到端延迟监控的不可替代性。</p><h3 id="性能基准测试方法" tabindex="-1">性能基准测试方法 <a class="header-anchor" href="#性能基准测试方法" aria-label="Permalink to &quot;性能基准测试方法&quot;">​</a></h3><ul><li>集群上线前，使用集群外部的独立机器进行性能测量</li><li>在施加负载的同时，延迟数据来自外部监控节点，更接近真实生产场景</li></ul><h2 id="性能容量规划" tabindex="-1">性能容量规划 <a class="header-anchor" href="#性能容量规划" aria-label="Permalink to &quot;性能容量规划&quot;">​</a></h2><h3 id="性能悬崖问题" tabindex="-1">性能悬崖问题 <a class="header-anchor" href="#性能悬崖问题" aria-label="Permalink to &quot;性能悬崖问题&quot;">​</a></h3><p>随着 IO 饱和度增加，集群会在某个拐点突然出现延迟急剧上升（从毫秒级跳升至秒级），这是生产环境中最危险的场景之一。</p><h3 id="容量定义的三大难点" tabindex="-1">容量定义的三大难点 <a class="header-anchor" href="#容量定义的三大难点" aria-label="Permalink to &quot;容量定义的三大难点&quot;">​</a></h3><ol><li><p><strong>IO 大小动态变化</strong>：多租户环境中，不同应用的 IO 大小差异极大（4K 随机写、MB 级日志写入等），性能阈值是动态的而非固定值。</p></li><li><p><strong>读写比例动态变化</strong>：不同应用读写比差异显著（50/50、80/20 等），且会因数据迁移、区域同步等操作发生剧烈变化，导致原本运行良好的集群突然成为瓶颈。</p></li><li><p><strong>延迟敏感度差异</strong>：同一集群上既有对延迟不敏感、追求高吞吐的应用，也有要求亚毫秒延迟的数据库类应用，两者需求相互冲突。</p></li></ol><h3 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h3><ul><li>以较大 IO 大小为基准进行 benchmarking，定义集群可承载的 IOPS 上限 X</li><li>实施超额分配（over-provisioning），基于历史 IO 模式（读写比、IO 大小、实际使用率、突发特征）动态调整超配系数</li><li>建立 top talker 识别机制，在出现 thundering herd 时快速定位并通过 admin 级别的 sub-QoS 进行限流</li><li>通过延迟指标判断扩容时机：当集群繁忙程度接近延迟目标阈值时，触发扩容决策</li></ul><h2 id="know-your-workload-项目" tabindex="-1">Know Your Workload 项目 <a class="header-anchor" href="#know-your-workload-项目" aria-label="Permalink to &quot;Know Your Workload 项目&quot;">​</a></h2><p>为解决性能容量可见性问题，沃尔玛内部开发了 &quot;Know Your Workload&quot; 项目：</p><ul><li>将OpenStack 外部数据（项目级、VM 级信息）与现有 RBD volume 级指标关联</li><li>实现对每个项目 IO 驱动方式、平均 IO 大小、读写访问模式的精细化洞察</li><li>能力：识别 top talker、缓解 noisy neighbor 问题、指导工作负载优化、支撑更智能的容量规划</li></ul><p><strong>技术展望</strong>：RBD 已支持 image metadata 存储，若能将项目级/VM 级信息作为 metadata 暴露为 Prometheus 指标，上述能力可原生实现。</p><h2 id="ceph-orchestrator-使用痛点" tabindex="-1">Ceph Orchestrator 使用痛点 <a class="header-anchor" href="#ceph-orchestrator-使用痛点" aria-label="Permalink to &quot;Ceph Orchestrator 使用痛点&quot;">​</a></h2><h3 id="定制化灵活性不足" tabindex="-1">定制化灵活性不足 <a class="header-anchor" href="#定制化灵活性不足" aria-label="Permalink to &quot;定制化灵活性不足&quot;">​</a></h3><ul><li>无法将两块驱动器配置为单个 OSD</li><li>自定义 BGP 网络场景下，orchestrator 无法感知自定义网络配置，导致集群 bootstrap 需要额外 workaround</li></ul><h3 id="大规模维护效率问题" tabindex="-1">大规模维护效率问题 <a class="header-anchor" href="#大规模维护效率问题" aria-label="Permalink to &quot;大规模维护效率问题&quot;">​</a></h3><ul><li>Ceph 升级仍只能逐台服务器操作，无法批量处理整个机架</li><li>对于内核补丁、OS 安装等维护操作，虽然目标是同时停止整个机架的服务，但 orchestrator 执行层面仍是逐台进行，大幅延长维护窗口</li><li><strong>期望功能</strong>：orchestrator 能感知集群拓扑，在不违反 failure domain 约束的前提下，支持批量将一组主机置入维护模式</li></ul><h3 id="配置漂移管理" tabindex="-1">配置漂移管理 <a class="header-anchor" href="#配置漂移管理" aria-label="Permalink to &quot;配置漂移管理&quot;">​</a></h3><ul><li>跨数十个集群的配置一致性难以保证</li><li>故障处理过程中的临时配置变更容易被遗忘，导致集群配置长期处于非预期状态</li><li>曾发生因遗留激进的 recovery 配置，在机架/交换机故障时反而加剧问题的情况</li><li><strong>期望功能</strong>：支持定义基线配置，并能自动检测和回滚配置漂移</li></ul><h2 id="社区反馈与路线图" tabindex="-1">社区反馈与路线图 <a class="header-anchor" href="#社区反馈与路线图" aria-label="Permalink to &quot;社区反馈与路线图&quot;">​</a></h2><p>演讲结束后，Ceph 社区开发者现场回应了大规模升级的痛点：</p><ul><li>正在开发基于拓扑感知的 orchestrator 模型，支持机架级批量升级</li><li>新增 <code>ok-to-upgrade</code> 命令，orchestrator 将利用该命令智能判断在不损失冗余性的前提下可同时升级的 OSD 数量</li></ul><h2 id="总结与建议" tabindex="-1">总结与建议 <a class="header-anchor" href="#总结与建议" aria-label="Permalink to &quot;总结与建议&quot;">​</a></h2><ul><li><strong>Ceph 不是免费的</strong>：大规模运营需要投入大量工程资源，小规模场景可能不适合</li><li><strong>达到一定规模后，Ceph 的 TCO 优于公有云和企业存储</strong></li><li><strong>监控是成功的基石</strong>：原生监控不足以支撑生产决策，必须建立外部端到端延迟监控</li><li><strong>硬件选型至关重要</strong>：从 SATA 到 SAS 再到 NVMe 的演进，每一步都有明确的性能驱动因素</li><li><strong>保守升级策略</strong>：大型零售企业受务节奏约束，版本升级必然滞后，这是现实而非缺陷</li><li><strong>延迟是扩容的核心指标</strong>：以延迟目标作为集群扩容的触发条件，而非单纯的容量百分比</li></ul>',58)])])}const b=e(o,[["render",t]]);export{p as __pageData,b as default};
